package ai.eva.android.probe;
import android.content.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;import org.json.*;
/** Metadata/history backup only; never includes auth, API keys, runtime or workspace files. */
final class DataBackupStore {
 static final int MAX_CHARS=2000000;
 static String current(Context c){return c.getSharedPreferences("eva-ui",0).getString("state","{\"chats\":[],\"drafts\":[],\"projects\":[]}");}
 static boolean running(JSONObject state)throws JSONException{for(String key:new String[]{"chats","drafts"}){JSONArray rows=state.optJSONArray(key);if(rows!=null)for(int i=0;i<rows.length();i++)if(rows.getJSONObject(i).optBoolean("running"))return true;}return false;}
 static void idle(Context c)throws Exception{if(VoiceAgent.busy||!PhoneTools.owner.isEmpty()||running(new JSONObject(current(c))))throw new IOException("请先停止正在执行的任务，再进行备份或恢复");File[] tasks=new File(c.getFilesDir().getCanonicalFile(),"alpine/root/eva-tasks").listFiles();if(tasks!=null)for(File dir:tasks){File state=new File(dir,"state.json");if(state.isFile()&&state.length()<65536){JSONObject value=new JSONObject(new String(Files.readAllBytes(state.toPath()),StandardCharsets.UTF_8));if(Arrays.asList("running","queued","starting").contains(value.optString("state")))throw new IOException("本地终端仍有任务，请先停止任务");}}}
 static JSONObject exportState(String raw)throws Exception{JSONObject source=new JSONObject(raw),out=new JSONObject();for(String key:new String[]{"chats","drafts","projects"})out.put(key,source.optJSONArray(key)==null?new JSONArray():source.getJSONArray(key));out.put("draft",source.optString("draft","")).put("active",source.opt("active")).put("projectId",source.optString("projectId",""));return out;}
 static byte[] encodeState(String raw)throws Exception{JSONObject manifest=new JSONObject().put("format","eva-android-history").put("version",1).put("createdAt",System.currentTimeMillis()).put("workspaceFiles",false).put("credentials",false).put("restoreMode","merge-read-only");return DataBackupArchive.encode(manifest.toString(),exportState(raw).toString());}
 static final class Preview {final JSONObject state;final int chats,drafts,projects;Preview(JSONObject s){state=s;chats=s.optJSONArray("chats").length();drafts=s.optJSONArray("drafts").length()+(s.optString("draft","").trim().isEmpty()?0:1);projects=s.optJSONArray("projects").length();}}
 static void validateChats(JSONObject state)throws Exception{for(String key:new String[]{"chats","drafts"}){JSONArray rows=state.getJSONArray(key);for(int i=0;i<rows.length();i++){JSONObject chat=rows.getJSONObject(i);for(String name:new String[]{"id","title","draft","providerId","model","effort","serviceTier","projectId"})if(chat.has(name)&&!chat.isNull(name)&&!(chat.opt(name) instanceof String))throw new IOException("备份会话字段格式无效："+name);JSONArray messages=chat.optJSONArray("messages");if(chat.has("messages")&&messages==null)throw new IOException("备份消息列表格式无效");if(messages!=null)for(int j=0;j<messages.length();j++)if(!(messages.opt(j) instanceof String)&&!(messages.opt(j) instanceof JSONObject))throw new IOException("备份消息格式无效");if(chat.has("kernelThread")&&!chat.isNull("kernelThread")){JSONObject thread=chat.optJSONObject("kernelThread");if(thread==null)throw new IOException("备份内核历史格式无效");JSONArray turns=thread.optJSONArray("turns");if(turns==null)throw new IOException("备份缺少回合列表");for(int j=0;j<turns.length();j++){JSONObject turn=turns.optJSONObject(j);if(turn==null)throw new IOException("备份回合格式无效");JSONArray items=turn.optJSONArray("items");if(items==null)throw new IOException("备份缺少回合消息");for(int k=0;k<items.length();k++){JSONObject item=items.optJSONObject(k);if(item==null)throw new IOException("备份回合消息格式无效");for(String field:new String[]{"content","summary","plan","contentItems"})if(item.has(field)&&!item.isNull(field)&&item.optJSONArray(field)==null)throw new IOException("备份消息字段格式无效："+field);}}}}}}
 static Preview preview(InputStream input)throws Exception{Map<String,String> files=DataBackupArchive.decode(input);for(String value:files.values())DataBackupArchive.checkJsonDepth(value);JSONObject manifest=new JSONObject(files.get("manifest.json"));if(!"eva-android-history".equals(manifest.optString("format"))||manifest.optInt("version")!=1||manifest.optBoolean("workspaceFiles")||manifest.optBoolean("credentials"))throw new IOException("此备份格式或版本不受支持");JSONObject state=new JSONObject(files.get("conversations.json"));for(String key:new String[]{"chats","drafts","projects"}){JSONArray rows=state.optJSONArray(key);if(rows==null||rows.length()>10000)throw new IOException("备份列表无效或数量过多");for(int i=0;i<rows.length();i++)if(!(rows.opt(i) instanceof JSONObject))throw new IOException("备份条目格式无效");}validateChats(state);return new Preview(state);}
 static JSONObject merge(JSONObject current,JSONObject incoming)throws Exception{
  JSONObject merged=new JSONObject(current.toString());JSONArray chats=merged.optJSONArray("chats");if(chats==null){chats=new JSONArray();merged.put("chats",chats);}JSONArray projects=merged.optJSONArray("projects");if(projects==null){projects=new JSONArray();merged.put("projects",projects);}Map<String,String> ids=new HashMap<>();
  JSONArray importedProjects=incoming.getJSONArray("projects");for(int i=0;i<importedProjects.length();i++){JSONObject old=importedProjects.getJSONObject(i);String id=UUID.randomUUID().toString();ids.put(old.optString("id"),id);projects.put(new JSONObject().put("id",id).put("name",old.optString("name","导入项目")+"（导入）").put("importedMetadataOnly",true));}
  for(String key:new String[]{"chats","drafts"}){JSONArray rows=incoming.getJSONArray(key);for(int i=0;i<rows.length();i++){JSONObject old=rows.getJSONObject(i),chat=new JSONObject(old.toString());chat.put("sourceConversationId",old.optString("id")).put("id",UUID.randomUUID().toString()).put("importedReadOnly",true).put("importedAt",System.currentTimeMillis()).put("running",false).put("pending","").put("projectId",ids.getOrDefault(old.optString("projectId"),""));chat.put("title",old.optString("title","导入对话")+"（导入历史）");if(chat.optJSONArray("messages")==null)chat.put("messages",new JSONArray());if(chat.optJSONArray("attachments")!=null)chat.put("importedAttachments",chat.getJSONArray("attachments"));chat.put("attachments",new JSONArray());JSONObject thread=chat.optJSONObject("kernelThread");if(thread!=null){JSONArray turns=thread.optJSONArray("turns");if(turns!=null)for(int n=0;n<turns.length();n++){JSONObject turn=turns.getJSONObject(n);if("inProgress".equals(turn.optString("status")))turn.put("status","interrupted").put("importedInterrupted",true);}}chats.put(chat);}}
  if(!incoming.optString("draft","").trim().isEmpty())chats.put(new JSONObject().put("id",UUID.randomUUID().toString()).put("title","未发送草稿（导入历史）").put("messages",new JSONArray()).put("draft",incoming.optString("draft")).put("running",false).put("importedReadOnly",true).put("importedAt",System.currentTimeMillis()).put("projectId",ids.getOrDefault(incoming.optString("projectId"),"")));
  if(merged.toString().length()>MAX_CHARS)throw new IOException("合并后会话数据超过当前存储上限，未恢复任何内容");return merged;
 }
 static File restore(Context context,Preview preview,String expectedRaw,long expectedRevision)throws Exception{
  idle(context);synchronized(ShellActivity.saveLock){if(ShellActivity.saveRevision.get()!=expectedRevision||!current(context).equals(expectedRaw))throw new IOException("当前会话已变化，请重新选择备份并确认，避免覆盖新内容");JSONObject merged=merge(new JSONObject(expectedRaw),preview.state);File base=context.getFilesDir().getCanonicalFile(),backups=new File(base,"history-backups");if(Files.isSymbolicLink(backups.toPath()))throw new IOException("备份目录不能使用链接");if(!backups.isDirectory()&&!backups.mkdirs())throw new IOException("无法建立恢复前备份目录");File before=new File(backups,"before-restore-"+System.currentTimeMillis()+"-"+UUID.randomUUID()+".zip");Files.write(before.toPath(),encodeState(expectedRaw),StandardOpenOption.CREATE_NEW);ShellActivity.saveRevision.incrementAndGet();if(!context.getSharedPreferences("eva-ui",0).edit().putString("state",merged.toString()).commit())throw new IOException("保存恢复数据失败，原数据备份已保留");return before;}
 }
}
